<script>const es=@json(route('trip-expenses-store',$trip)),eu=@json(route('trip-expenses-update',[$trip,'__ID__'])),ex=@json(route('trip-expenses-status',[$trip,'__ID__']));function ed(x){return x?JSON.parse(atob(x)):{} }function openExpense(x){let d=ed(x),f=expenseForm;f.reset();f.action=es;expenseMethod.innerHTML='';expenseTitle.textContent=d.id?'Edit Expense':'Add New Expense';['expense_type','expense_date','amount','description'].forEach(k=>f.elements[k].value=d[k]||'');f.querySelector('[type=checkbox]').checked=d.id?!!d.reimbursable:true;if(d.id){f.action=eu.replace('__ID__',d.id);expenseMethod.innerHTML='<input type="hidden" name="_method" value="PUT">'}}function expenseStatus(x){let d=ed(x);expenseStatusForm.action=ex.replace('__ID__',d.id);expenseStatusForm.elements.status.value=d.status}document.addEventListener('DOMContentLoaded',()=>{expenseForm.onsubmit=e=>{let miss=['expense_type','expense_date','amount'].find(k=>!expenseForm.elements[k].value);if(miss){e.preventDefault();Swal.fire({icon:'error',text:'Please complete all required fields.'})}};document.querySelectorAll('.expense-delete').forEach(f=>f.onsubmit=e=>{if(f.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete expense?',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){f.dataset.ok=1;f.submit()}})})})</script>
